 "what_you_observe": [
  "Tuesday, February 2, 2016. Six am in the Hearthside Hotel. Three bright radio notes. A delivery van backfires twice.",
  "The crew meets for coffee at the hotel. The afternoon is open. A coat-check envelope holds the TV crew’s return fares. The party is at the ballroom tonight. A stranded driver needs a jack, and the ballroom piano is free.",
  "The Rialto is closing. The regional line can carry one last reel out of town. Alma wants her daughter in Pittsburgh to hear her voice."
 ],
 "your_own_memories": [],
 "who_you_are_with": "the TV crew in the lobby",
 "physical_choices": {
  "film_Alma": "Spend the last charged recording on Alma at the Rialto.",
  "film_party": "Use the last charge on the festival rehearsal.",
  "keep_battery": "Keep your battery and wait at the hotel."
 }
}

message.content:
{
 "action": "film_Alma",
 "words": "Hold the mic steady. Let the light hit her face.",
 "intention": "Capture the projectionist's final voice for her daughter before the Rialto closes.",
 "detail": "I should be in the lobby right now, handing the battery to the lead producer for the ballroom rehearsal. But I’m walking to the Rialto. The battery is dead on my hand, warm from the grip. I’m going to use it all on her. It’s the only thing that feels like it belongs to her, not to the schedule."
}
